use super::*;
fn observe<T>(work:impl FnOnce()->T)->(T,usize,usize){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(work);(value,heap.requested_bytes,heap.released_bytes)}
fn decode<T:semio_framework_value::FromValue>(text:&str)->T{let mut receive=|_|true;let mut control=semio_framework_value::NativeDecodeControl::new(16*1024*1024,&mut receive);semio_framework_pack_json::from_json_str_controlled(text,semio_framework_pack_json::JsonMemberPolicy::Reject,&mut control).unwrap()}
#[derive(semio_framework_value::RetireOwned)]
struct Sources{snapshot:FlowHostSnapshot,channels:EvalChannels,infos:HistoryFoldIndex<String,OperatorInfo>,cursor:FlowDisplayCursor}
#[test]
fn original_display_borrows_same_channels_and_closes_every_paid_projection(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
 for row in fixture["cases"].as_array().unwrap(){for copy in [1,3,64]{for cancel in [None,Some(0),Some(9),Some(37),Some(101)]{
  let(mut source,born,free)=observe(||{let snapshot=decode(&serde_json::json!({"schema":"flow.host_snapshot","camera":{"x":0,"y":0,"zoom":1},"widgets":row["widgets"],"synapses":[],"layout":{}}).to_string());let mut infos=HistoryFoldIndex::new();for(kind,info)in row["kindInfos"].as_object().unwrap(){let inputs=info["inputs"].as_array().unwrap().iter().map(|name|neural::ChannelSpec::requires(name.as_str().unwrap(),&[] as &[&str])).collect();let variadic_input=info["variadicSlot"].as_str().map(|key|neural::VariadicSpec{slot_key:key.into(),min:0,max:None});infos.insert(kind.clone(),OperatorInfo{inputs,variadic_input,..Default::default()});}Sources{snapshot,channels:EvalChannels{inputs:decode(&row["inputs"].to_string()),outputs:decode(&row["outputs"].to_string())},infos,cursor:FlowDisplayCursor::new()}});let original=born-free;let pointer=source.channels.outputs.iter().next().unwrap().1 as *const Dictionary;let(mut births,mut releases,mut idle)=(0,0,0);let mut minimum=0;
  for turn in 0..100000{if cancel==Some(turn){break}let d=source.cursor.demands(&source.snapshot,&source.channels,&source.infos).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(p,born,free)=observe(||source.cursor.step(&source.snapshot,&source.channels,&source.infos,RetainedCloneGrant{maximum_items:0,..grant}).unwrap());assert_eq!(p,Default::default());assert_eq!((born,free),(0,0));let(p,born,free)=observe(||source.cursor.step(&source.snapshot,&source.channels,&source.infos,grant).unwrap());assert!(p.fits(grant));assert_eq!((born,free),(p.retained_capacity_bytes,p.released_bytes));births+=born;releases+=free;assert_eq!(source.channels.outputs.iter().next().unwrap().1 as *const Dictionary,pointer);if source.cursor.complete(){break}if d.copy_bytes>copy{minimum=d.copy_bytes;assert_eq!(p,Default::default());break}if p==Default::default(){idle+=1}else{idle=0}assert!(idle<64,"original display stalled copy={copy} turn={turn} stage={} demand={d:?}",source.cursor.stage);}
  if cancel.is_none(){if minimum>copy{assert!(!source.cursor.complete());assert!(minimum<=4);}else{assert!(source.cursor.complete());let text=source.cursor.text.as_ref().unwrap();let actual:serde_json::Value=serde_json::from_str(text).unwrap();assert_eq!(actual,row["expected"]);}}
  let(mut owner,born,free)=observe(||ControlledRetirement::new(source).unwrap_or_else(|_|unreachable!()));assert_eq!((born,free),(0,0));idle=0;for turn in 0..100000{if owner.terminal_is_empty(){break}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()};let(step,born,free)=observe(||owner.step(grant).unwrap());let p=step.progress();assert!(p.fits(grant));assert_eq!((born,free),(p.retained_capacity_bytes,p.released_bytes));births+=born;releases+=free;if p==Default::default(){idle+=1}else{idle=0}assert!(idle<64,"original display close stalled copy={copy} turn={turn} grant={grant:?}");}assert!(owner.terminal_is_empty());assert_eq!(original+births,releases);assert_eq!(observe(||drop(owner)),((),0,0));eprintln!("[DEBUG] Original display case={} copy={copy} cancel={cancel:?} channelPointer=true terminalDrop=0",row["id"]);
 }}}
}
